"""Run the plan lint rows.

Usage, from the repository root:

    python3 -I <skill>/scripts/lint.py [--row N] <slug>

<slug> is the workspace directory name under docs/plans/ and must match [a-z0-9][a-z0-9.-]*.
references/guides/lint-spec.md specifies each row: what it checks, its pass condition and its severity.
This file holds each row's program, byte for byte, as the constant ROW_NN. A run substitutes the slug
for every <slug> in the program and runs it with `sh -c` in the current directory.

With --row N, it runs row N and passes the row's stdout, stderr and exit status through unchanged.
Without --row, it runs rows 1-19 in order, prints each row's stdout under a `row N` header line (its
stderr goes to stderr), and ends with `lint: K/19 rows silent`, where K counts the rows that printed
nothing. It then exits 0 only when every row passes: no stderr, an allowed exit (0; 0 or 1 for rows 5,
6, 11, 15 and 16), no output except a warn finding (rows 8, 13 and 15), and exit 1 for a silent row 5
or 0 for any other silent row except 15. It exits 1 otherwise and 2 on a usage error or an invalid slug.

The programs use plain sh, grep, sed and awk only, and none of them contains the pipe character:
shell `A || B` is spelled `if A; then :; else B; fi`, an alternation in awk is spelled as summed tests,
and a table separator is `sprintf("%c",124)`.
"""
import os
import re
import signal
import subprocess
import sys

ROW_01 = r'''ws=docs/plans/<slug>; if [ -f docs/plans/<slug>/plan.md ] && [ "$(sed -n '1p' docs/plans/<slug>/plan.md)" = 'Gate: Lite' ]; then for f in "$ws/log.md" "$ws/log-archive.md" "$ws/usage.md"; do if ! { [ ! -e "$f" ] && [ ! -L "$f" ]; }; then echo "migrate first: $ws is a Focused workspace on ${f##*/} (references/guides/migrate.md)"; exit 1; fi; done; for f in "$ws/plan.md" "$ws/history.md" "$ws/resource-usage.md"; do if [ ! -f "$f" ]; then echo "row1: Lite missing $f"; exit 1; fi; done; for f in "$ws/board.md" "$ws/task-board.md" "$ws/tasks" "$ws/points"; do if ! { [ ! -e "$f" ] && [ ! -L "$f" ]; }; then echo "row1: Lite has Full artifact $f"; exit 1; fi; done; if awk 'function trim(s){sub(/^[[:space:]]+/,"",s); sub(/[[:space:]]+$/,"",s); return s} ($0 ~ /^ ? ? ?```/) + ($0 ~ /^ ? ? ?~~~/){t=trim($0); if(!match(t,/^```+/)) match(t,/^~~~+/); marker=substr(t,RSTART,RLENGTH); tail=trim(substr(t,RLENGTH+1)); if(!fence) fence=marker; else if(substr(marker,1,1)==substr(fence,1,1) && length(marker)>=length(fence) && tail=="") fence=""; next} !fence && ((($0 " ") ~ /^ ? ? ?##[[:space:]]+5[.] Point decomposition[[:space:]]/) + (($0 " ") ~ /^ ? ? ?##[[:space:]]+5[.] Task decomposition[[:space:]]/)){print "row1: Lite has Full Task decomposition"; bad=1} END{if(bad) exit 1}' docs/plans/<slug>/plan.md; then :; else exit $?; fi; fi; set --; for f in docs/plans/<slug>/*.md docs/plans/<slug>/*/*.md; do case "$f" in docs/plans/<slug>/legacy-*/*) continue;; esac; if ! { [ ! -e "$f" ] && [ ! -L "$f" ]; }; then set -- "$@" "$f"; fi; done; if [ "$#" -eq 0 ]; then echo "row1: missing workspace files"; exit 1; fi; awk 'BEGIN{f=0} /^```/{f=!f; next} !f && /[{][{]/{print FILENAME ":" FNR ": " $0}' "$@"'''
ROW_02 = r'''ws=docs/plans/<slug>; board="$ws/task-board.md"; if [ -f docs/plans/<slug>/plan.md ] && [ "$(sed -n '1p' docs/plans/<slug>/plan.md)" = 'Gate: Lite' ]; then exit 0; fi; if [ -f "$ws/task-board.md" ] && grep -Eq '^Schema: tackle-workspace/5$' "$ws/task-board.md"; then :; else echo "migrate first: $ws has no tackle-workspace/5 task-board.md with LF line endings (references/guides/migrate.md)"; exit 1; fi; for f in "$ws/board.md" "$ws/log.md" "$ws/usage.md" "$ws/log-archive.md" "$ws/coordinator.md" "$ws/HANDOFF.md" "$ws/evidence" "$ws/points"; do if ! { [ ! -e "$f" ] && [ ! -L "$f" ]; }; then echo "mixed workspace paths: $f"; exit 1; fi; done; for f in "$ws/plan.md" "$ws/history.md" "$ws/resource-usage.md"; do if [ ! -f "$f" ]; then echo "missing: $f"; exit 1; fi; done; if [ ! -d "$ws/tasks" ]; then echo "missing tasks directory: $ws"; exit 1; fi; prefix=T-; set -- "$ws"/tasks/*.md; if [ ! -f "$1" ]; then echo "missing task briefs: $ws"; exit 1; fi; if awk -v prefix="$prefix" -v ws="$ws" -v boardfile="$board" -v agents="$ws/AGENTS.md" 'BEGIN{FS=sprintf("%c",124); ag_pipe=sprintf("%c",124); ag_hdr=0; ag_seen=0; ag_incomment=0; nref=0; while((getline ag_line < agents)>0){ ag_out=""; ag_rest=ag_line; while(1){ if(ag_incomment){ ag_p=index(ag_rest,"-->"); if(ag_p==0){ag_rest=""; break} ag_rest=substr(ag_rest,ag_p+3); ag_incomment=0; continue } ag_p=index(ag_rest,"<!--"); if(ag_p==0){ag_out=ag_out ag_rest; break} ag_out=ag_out substr(ag_rest,1,ag_p-1); ag_rest=substr(ag_rest,ag_p+4); ag_incomment=1 } if(ag_incomment) continue; ag_t=trim(ag_out); if(substr(ag_t,1,3)=="```"){fence=!fence; continue} if(fence) continue; if(!ag_seen && ag_t=="## Sibling workspaces"){section=1; ag_seen=1; ag_hdr=0; continue} if(substr(ag_out,1,3)=="## "){section=0; continue} if(!section) continue; if(!(substr(ag_t,1,1)==ag_pipe && substr(ag_t,length(ag_t),1)==ag_pipe && length(ag_t)>1)) continue; ag_n=split(ag_t,ag_cell,ag_pipe); ag_c1=trim(ag_cell[2]); ag_c2=trim(ag_cell[3]); if(!ag_hdr){ if(ag_n==5 && ag_c1=="Sibling" && ag_c2=="Path" && trim(ag_cell[4])=="Relation") ag_hdr=1; continue} if(ag_n!=5) continue; sub(/^`+/,"",ag_c2); sub(/`+$/,"",ag_c2); ag_c2=trim(ag_c2); if(!(ag_c1 ~ /^[a-z0-9][a-z0-9-]*$/)) continue; if(substr(ag_c2,1,11)!="docs/plans/") continue; ag_name=substr(ag_c2,12); if(!(ag_name ~ /^[a-z0-9][a-z0-9-]*$/)) continue; if(!(ag_c1 in sibling)) sibling[ag_c1]=ag_name } close(agents); fence=""; section=0} function sibscan(s,owner,record,   m,ref,slug,key,out){ out=""; while(match(s,/T-[0-9]+ [[][a-z0-9][a-z0-9-]*[]]/)){ m=substr(s,RSTART,RLENGTH); ref=substr(m,1,index(m," ")-1); slug=substr(m,index(m,"[")+1); slug=substr(slug,1,length(slug)-1); if(record){ key=owner SUBSEP ref SUBSEP slug; if(!(key in sseen)){sseen[key]=1; sref[++nref]=key} } if(record + (slug in sibling)) out=out substr(s,1,RSTART-1) " "; else out=out substr(s,1,RSTART+RLENGTH-1); s=substr(s,RSTART+RLENGTH) } return out s} function sibbrief(b,   rest,sx,name,file,s){ rest=substr(b,4); sx=index(rest,"/"); if(sx<2) return ""; name=substr(rest,1,sx-1); if(substr(rest,sx+1,6)!="tasks/") return ""; file=substr(rest,sx+7); if(file=="") return ""; if(index(file,"/")>0) return ""; if(index(file,"..")>0) return ""; for(s in sibling) if(sibling[s]==name) return "docs/plans/" name "/tasks/" file; return ""} function trim(s){sub(/^[[:space:]]+/,"",s); sub(/[[:space:]]+$/,"",s); return s} function refs(s,id){while(match(s,/[PT]-[A-Za-z0-9]+(-[A-Za-z0-9]+)*/)){id=substr(s,RSTART,RLENGTH); used[id]=1; s=substr(s,RSTART+RLENGTH)}} FILENAME==ws "/plan.md" {if(($0 ~ /^ ? ? ?```/) + ($0 ~ /^ ? ? ?~~~/)){t=trim($0); if(!match(t,/^```+/)) match(t,/^~~~+/); marker=substr(t,RSTART,RLENGTH); tail=trim(substr(t,RLENGTH+1)); if(!fence) fence=marker; else if(substr(marker,1,1)==substr(fence,1,1) && length(marker)>=length(fence) && tail=="") fence=""; next} if(fence) next; if((($0 " ") ~ /^ ? ? ?##[[:space:]]+5[.] Point decomposition[[:space:]]/) + (($0 " ") ~ /^ ? ? ?##[[:space:]]+5[.] Task decomposition[[:space:]]/)){section=1; next} if(($0 " ") ~ /^ ? ? ?##?[[:space:]]/) section=0; if(section && NF>1 && $1 ~ /^[[:space:]]*$/){id=trim($2); sub(/^[*][*]/,"",id); sub(/[*][*]$/,"",id); if(match(id,/^[PT]-[A-Za-z0-9]+(-[A-Za-z0-9]+)*/)){id=substr(id,RSTART,RLENGTH); declared[id]=1; if(substr(id,1,2)!=prefix) print "mixed plan identity: " id}} next} FILENAME==boardfile {id=trim($2); if(id ~ /^[PT]-[A-Za-z0-9]+(-[A-Za-z0-9]+)*$/){used[id]=1; board[id]=1; if(substr(id,1,2)!=prefix) print "mixed board identity: " id; refs(sibscan($5,id,1)); brief=trim($4); if(brief ~ /^`[^`]+`$/) brief=substr(brief,2,length(brief)-2); path=""; if(index(brief,"../")==1){path=sibbrief(brief); if(path=="") print "brief " brief " for task " id " is outside the workspace"} else {if(index(brief,"tasks/")!=1) print "mixed brief path: " brief; path=ws "/" brief} if(path!=""){result=0; first=""; while((getline line < path)>0){result=1; if((line ~ /^[[:space:]]*$/) + (line ~ /^[[:space:]]*<a[[:space:]]+id=/)) continue; first=line; break} close(path); if(result<1) print "missing brief: " brief; else if((first " ") !~ ("^# Task " id "[[:space:]]")) print "mismatched brief heading: " brief} } next} (($0 " ") ~ /^[[:space:]]*#[[:space:]]*[PT]-[A-Za-z0-9]+(-[A-Za-z0-9]+)*[[:space:]]/) + (($0 " ") ~ /^[[:space:]]*#[[:space:]]*Task[[:space:]]+[PT]-[A-Za-z0-9]+(-[A-Za-z0-9]+)*[[:space:]]/) {ln=sibscan($0,"",0); if(match(ln,/[PT]-[A-Za-z0-9]+(-[A-Za-z0-9]+)*/)) used[substr(ln,RSTART,RLENGTH)]=1} /^[[:space:]]*(-[[:space:]]*)?([*][*])?Depends([ -])on([*][*])?:/ {refs(sibscan($0,"",0))} END{for(k=1;k<=nref;k++){split(sref[k],sp,SUBSEP); owner=sp[1]; rf=sp[2]; sl=sp[3]; if(!(sl in sibling)){print "task " owner " depends on " rf " [" sl "], but no sibling named " sl " is declared"; continue} if(!(sl in bstate)){bstate[sl]="refused"; bp="docs/plans/" sibling[sl] "/task-board.md"; while((getline bl < bp)>0){if(bl=="Schema: tackle-workspace/5") bstate[sl]="ok"; nb=split(bl,bf,sprintf("%c",124)); if(nb>=2) sboard[sl SUBSEP trim(bf[2])]=1} close(bp); if(bstate[sl]=="refused") print "sibling " sl " has no tackle-workspace/5 task-board.md at docs/plans/" sibling[sl]} if(bstate[sl]=="refused") continue; if(!((sl SUBSEP rf) in sboard)) print "task " owner " depends on " rf " [" sl "], which is not on the sibling" sprintf("%c",39) "s board"} for(id in used) if(!(id in declared)) print "unresolved: " id; for(id in declared) if(!(id in board)) print "missing board task: " id}' "$ws/plan.md" "$board" "$@"; then :; else exit $?; fi
ag="$ws/AGENTS.md"; if [ -f "$ag" ]; then :; else ag=/dev/null; fi; set -- "$ag" "$board" "$ws/plan.md"; for b in $(awk -v P="$ws/" 'BEGIN{FS=sprintf("%c",124)} /^```/{f=!f; next} f{next} substr($0,1,1)==sprintf("%c",124) { if (bc==0) { for(i=2;i<NF;i++){ c=$i; gsub(/^[[:space:]]+/,"",c); gsub(/[[:space:]]+$/,"",c); if (c=="Brief") bc=i } next } c=$bc; gsub(/[`[:space:]]/,"",c); if (c ~ /^tasks\/[^\/]+\.md$/) print P c }' "$board"); do if [ -f "$b" ]; then set -- "$@" "$b"; fi; done
awk -v P="$ws/" '
function trim(s){ gsub(/^[[:space:]]+/,"",s); gsub(/[[:space:]]+$/,"",s); return s }
function closed(t){ return (st[t]=="Complete") + (st[t]=="Skipped") + (st[t]=="Unverifiable") }
function sibstatus(slug,id,   path,line,n,c,i,h,sc,tc,r){ if (!(slug in sibling)) return ""; path="docs/plans/" sibling[slug] "/task-board.md"; h=0; r=""
  while ((getline line < path) > 0) { if (substr(line,1,1)!=sprintf("%c",124)) continue; n=split(line,c,sprintf("%c",124))
    if (!h) { for(i=2;i<n;i++){ if (trim(c[i])=="Status") sc=i; if (trim(c[i])=="Task") tc=i } if (sc && tc) h=1; continue }
    if (trim(c[tc])==id) r=trim(c[sc]) }
  close(path); return r }
BEGIN{ FS=sprintf("%c",124) }
FNR==1 { fence=0 }
FILENAME ~ /AGENTS\.md$/ {
  if ($0 ~ /^```/) { fence=!fence; next } if (fence) next
  if ($0 ~ /^## Sibling workspaces/) { insib=1; next } if ($0 ~ /^## /) { insib=0; next }
  if (insib && substr($0,1,1)==sprintf("%c",124)) { a=trim($2); b=trim($3); gsub(/`/,"",b); if (a ~ /^[a-z0-9][a-z0-9-]*$/ && substr(b,1,11)=="docs/plans/" && substr(b,12) ~ /^[a-z0-9][a-z0-9-]*$/) sibling[a]=substr(b,12) }
  next }
FILENAME ~ /task-board\.md$/ {
  if ($0 ~ /^```/) { fence=!fence; next } if (fence) next
  if (substr($0,1,1)!=sprintf("%c",124)) next
  if (!hdr) { for(i=2;i<NF;i++){ c=trim($i); if(c=="Task") tc=i; if(c=="Brief") bc=i; if(c=="Depends on") dc=i; if(c=="Status") sc=i } if (tc && bc) hdr=1; next }
  t=trim($tc); gsub(/[*`]/,"",t); if (t !~ /^T-[0-9]+$/) next
  nt++; order[nt]=t; b=$bc; gsub(/[`[:space:]]/,"",b); task[P b]=t; st[t]=trim($sc); d=$dc; gsub(/`/,"",d); dep[t]=d; next }
FILENAME ~ /plan\.md$/ {
  if ($0 ~ /^```/) { fence=!fence; next } if (fence) next
  if (($0 ~ /^## 5\. Task decomposition/) + ($0 ~ /^## 5\. Point decomposition/)) { in5=1; next } if ($0 ~ /^##? /) { in5=0; next }
  if ((!in5) + (substr($0,1,1)!=sprintf("%c",124))) next
  if (!tracehdr) { for(i=2;i<NF;i++){ c=trim($i); if(c=="Task") taskcol=i; if(c=="Traces to") tracecol=i } if (taskcol && tracecol) tracehdr=1; next }
  id=$taskcol; if (!match(id,/T-[0-9]+/)) next; id=substr(id,RSTART,RLENGTH); r=$tracecol
  while (match(r,/`[^`]+`/)) { k=substr(r,RSTART+1,RLENGTH-2); r=substr(r,RSTART+RLENGTH); if (!((k SUBSEP id) in seenk)) { seenk[k,id]=1; nk[k]++; tracer[k,nk[k]]=id; if (!(k in kseen)) { kseen[k]=1; nkeys++; keys[nkeys]=k } } }
  next }
{ t=task[FILENAME] }
/^```/ { fence=!fence; next } fence { next }
/^[[:space:]]*[-*+][[:space:]]+[*][*]Lineage[*][*]:/ { if (!closed(t)) { l=$0; while (match(l,/T-[0-9]+/)) { successor[substr(l,RSTART,RLENGTH)]=1; l=substr(l,RSTART+RLENGTH) } } }
END {
  for (i=1;i<=nt;i++) { t=order[i]; if (closed(t)) continue; d=dep[t]
    while (match(d,/T-[0-9]+( [[][a-z0-9][a-z0-9-]*[]])?/)) { ref=substr(d,RSTART,RLENGTH); d=substr(d,RSTART+RLENGTH)
      if (index(ref," [")) { id=substr(ref,1,index(ref," ")-1); slug=substr(ref,index(ref,"[")+1); slug=substr(slug,1,length(slug)-1); if (sibstatus(slug,id)=="Skipped") printf "dependency on skipped: %s on %s\n", t, ref }
      else if (st[ref]=="Skipped") printf "dependency on skipped: %s on %s\n", t, ref } }
  for (i=1;i<=nkeys;i++) { k=keys[i]; dead=1; for (j=1;j<=nk[k];j++) { o=tracer[k,j]; if (st[o]!="Skipped") dead=0; else if (o in successor) dead=0 }
    if (dead) printf "dead requirement owner: %s\n", k }
}' "$@"'''
ROW_03 = r'''ws=docs/plans/<slug>; board="$ws/task-board.md"; if [ -f docs/plans/<slug>/plan.md ] && [ "$(sed -n '1p' docs/plans/<slug>/plan.md)" = 'Gate: Lite' ]; then exit 0; fi; if [ -f "$ws/task-board.md" ] && grep -Eq '^Schema: tackle-workspace/5$' "$ws/task-board.md"; then :; else echo "migrate first: $ws has no tackle-workspace/5 task-board.md with LF line endings (references/guides/migrate.md)"; exit 1; fi; awk 'BEGIN{FS=sprintf("%c",124)} function cell(i,c){c=$i; sub(/^[[:space:]]+/,"",c); sub(/[[:space:]]+$/,"",c); return c} function colof(name,i){for(i=2;i<=NF;i++) if(cell(i)==name) return i; return 0} FNR==1{col=0; pend=0} pend && $2 ~ /^[[:space:]]*:?-+:?[[:space:]]*$/ {col=pend} {pend=0} $2 !~ /[PT]-[A-Za-z0-9]/ && colof("Status"){pend=colof("Status")} $2 ~ /^[[:space:]]*[PT]-[A-Za-z0-9]+(-[A-Za-z0-9]+)*[[:space:]]*$/ && NF>3 {status=cell(col ? col : 6); ok=(status=="Draft") + (status=="Ready to run") + (status=="In progress") + (status=="Checking") + (status=="Complete") + (status=="Blocked") + (status=="Interrupted") + (status=="Skipped") + (status=="Unverifiable") + (status=="Waiting on owner"); if(!ok) print "bad status:" $0}' "$board"'''
ROW_04 = r'''set -- docs/plans/<slug>/plan.md docs/plans/<slug>/reference.md; for f in docs/plans/<slug>/tasks/*.md; do if [ -f "$f" ]; then set -- "$@" "$f"; fi; done; if [ -f docs/plans/<slug>/plan.md ] && [ "$(sed -n '1p' docs/plans/<slug>/plan.md)" = 'Gate: Lite' ]; then set -- docs/plans/<slug>/plan.md; if ! { [ ! -e docs/plans/<slug>/reference.md ] && [ ! -L docs/plans/<slug>/reference.md ]; }; then set -- "$@" docs/plans/<slug>/reference.md; fi; fi; awk 'function check(c,p,n,q,s,ok,f,i,L){p=c; sub(/:.*/,"",p); n=c; sub(/^[^:]*:/,"",n); n=n+0; split(c,q,"\""); s=q[2]; ok=0; f=p; i=0; while((getline L < f)>0){i++; if(i==n && index(L,s)) ok=1} close(f); if(i==0){f="docs/plans/<slug>/" p; while((getline L < f)>0){i++; if(i==n && index(L,s)) ok=1} close(f)} if(!ok) print FILENAME ":" FNR " stale: " c} {rest=$0; while(match(rest,/[A-Za-z0-9_\/.-]+\.[a-z]+:[0-9]+(-[0-9]+)? — "/)){head=substr(rest,RSTART,RLENGTH); rest=substr(rest,RSTART+RLENGTH); if(match(rest,/^[^"]+"/)){check(head substr(rest,1,RLENGTH)); rest=substr(rest,RLENGTH+1)} else {print FILENAME ":" FNR " malformed: " head rest; rest=""}}}' "$@"'''
ROW_05 = r'''ws=docs/plans/<slug>; if [ -f docs/plans/<slug>/plan.md ] && [ "$(sed -n '1p' docs/plans/<slug>/plan.md)" = 'Gate: Lite' ]; then exit 1; fi; if [ -f "$ws/task-board.md" ] && grep -Eq '^Schema: tackle-workspace/5$' "$ws/task-board.md"; then :; else echo "migrate first: $ws has no tackle-workspace/5 task-board.md with LF line endings (references/guides/migrate.md)"; exit 1; fi; set -- docs/plans/<slug>/plan.md; for f in docs/plans/<slug>/tasks/*.md; do if [ -f "$f" ]; then set -- "$@" "$f"; fi; done; if awk '/^```/{f=!f;next} !f && /^[[:space:]]*(-[[:space:]]*)?([*][*])?Status([*][*])?:/ {print FILENAME ":" FNR ": duplicated Status declaration";bad=1} END{exit !bad}' "$@"; then exit 0; else code=$?; if [ "$code" -ne 1 ]; then exit "$code"; fi; fi; grep -n -e 🔴 -e 🟡 -e ⏸ -e 🟢 -e ⚪ "$@"'''
ROW_06 = r'''ws=docs/plans/<slug>; history="$ws/history.md"; archive="$ws/history-archive.md"; set -e; if [ ! -f "$history" ]; then echo "row6: missing ${history##*/}"; exit 1; fi; for f in "$archive" "$history"; do if [ -f "$f" ]; then awk 'BEGIN{prev=""} /^## 20[0-9][0-9]-[0-9][0-9]-[0-9][0-9]/{d=substr($2,1,10); if(prev != "" && d < prev) {print "row6: out of order: " FILENAME ": " $0; bad=1} prev=d} END{if(bad) exit 1}' "$f"; fi; done; if [ -f "$archive" ]; then awk 'FNR==1{file++} file==1 && /^## 20[0-9][0-9]-[0-9][0-9]-[0-9][0-9]/{archive_last=substr($2,1,10)} file==2 && /^## 20[0-9][0-9]-[0-9][0-9]-[0-9][0-9]/ && history_first==""{history_first=substr($2,1,10)} END{if(archive_last!="" && history_first!="" && archive_last>history_first){print "row6: archive newer than log oldest: " archive_last " > " history_first; exit 1}}' "$archive" "$history"; fi'''
