SLUG = re.compile(r'[a-z0-9][a-z0-9.-]*')


def program(number, slug):
    """Row `number`'s program with the slug substituted, as UTF-8 bytes."""
    return globals()['ROW_%02d' % number].replace('<slug>', slug).encode('utf-8')


def passes(number, code, stdout, stderr):
    if stderr or code not in ((0, 1) if number in (5, 6, 11, 15, 16) else (0,)):
        return False
    if stdout:
        return number in (8, 13, 15)
    return code == 1 if number == 5 else (number == 15 or code == 0)


def main(argv):
    number = None
    if len(argv) == 4 and argv[1] == '--row' and argv[2].isdigit() and 1 <= int(argv[2]) <= 19:
        number = int(argv[2])
    elif len(argv) != 2:
        print('usage: python3 -I <skill>/scripts/lint.py [--row N] <slug>', file=sys.stderr)
        return 2
    slug = argv[-1]
    if not SLUG.fullmatch(slug):
        print('lint: invalid slug %r' % slug, file=sys.stderr)
        return 2
    if number is not None:
        code = subprocess.run([b'sh', b'-c', program(number, slug)]).returncode
        if code < 0:
            signal.signal(-code, signal.SIG_DFL)
            os.kill(os.getpid(), -code)
        return code
    silent = 0
    ok = True
    for number in range(1, 20):
        result = subprocess.run([b'sh', b'-c', program(number, slug)], capture_output=True)
        sys.stdout.buffer.write(b'row %d\n' % number + result.stdout)
        sys.stdout.buffer.flush()
        sys.stderr.buffer.write(result.stderr)
        sys.stderr.buffer.flush()
        silent += not (result.stdout or result.stderr)
        ok = ok and passes(number, result.returncode, result.stdout, result.stderr)
    print('lint: %d/19 rows silent' % silent)
    return 0 if ok else 1


if __name__ == '__main__':
    sys.exit(main(sys.argv))
